package run.ikaros.sharing; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class RoomCommentService{private final RoomRepository rooms;private final RoomMembershipRepository members;private final RoomCommentRepository comments;public RoomCommentService(RoomRepository r,RoomMembershipRepository m,RoomCommentRepository c){rooms=r;members=m;comments=c;}public Mono<RoomCommentView> publish(UUID a,UUID roomId,PublishRoomCommentRequest q){return access(a,roomId).then(comments.findByRoomIdAndAuthorIdAndIdempotencyKey(roomId,a,q.idempotencyKey()).switchIfEmpty(Mono.defer(()->{Instant n=Instant.now();return comments.save(new RoomCommentEntity(null,roomId,a,q.idempotencyKey(),q.body(),false,n,n,null));}))).map(this::view);}public Flux<RoomCommentView> list(UUID a,UUID roomId){return access(a,roomId).thenMany(comments.findAllByRoomIdAndDeletedFalseOrderByCreatedAtAsc(roomId).map(this::view));}public Mono<RoomCommentView> edit(UUID a,UUID id,EditRoomCommentRequest q){return comments.findById(id).filter(c->c.authorId().equals(a)&&!c.deleted()).switchIfEmpty(Mono.error(new NotFoundException("Comment 不存在或无权编辑"))).flatMap(c->comments.save(new RoomCommentEntity(c.id(),c.roomId(),c.authorId(),c.idempotencyKey(),q.body(),false,c.createdAt(),Instant.now(),c.version()))).map(this::view);}public Mono<RoomCommentView> delete(UUID a,UUID id){return comments.findById(id).filter(c->c.authorId().equals(a)&&!c.deleted()).switchIfEmpty(Mono.error(new NotFoundException("Comment 不存在或无权删除"))).flatMap(c->comments.save(new RoomCommentEntity(c.id(),c.roomId(),c.authorId(),c.idempotencyKey(),c.body(),true,c.createdAt(),Instant.now(),c.version()))).map(this::view);}private Mono<Void> access(UUID a,UUID id){return rooms.findById(id).flatMap(r->members.findByRoomIdAndPrincipalId(id,a).filter(m->m.leftAt()==null).then()).switchIfEmpty(Mono.error(new NotFoundException("Room 不存在或无权访问")));}private RoomCommentView view(RoomCommentEntity c){return new RoomCommentView(c.id(),c.roomId(),c.authorId(),c.body(),c.deleted(),c.createdAt(),c.updatedAt());}}
